def unique_paths(grid):
    rows, cols = len(grid), len(grid[0])
    ways = [0] * cols            # ways[c]: paths to the cell in column c, for the row being processed
    ways[0] = 1                  # one way to stand on the start cell (unless it is blocked, see below)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                ways[c] = 0                  # nothing can enter a blocked cell
            elif c > 0:
                ways[c] += ways[c - 1]       # ways[c] still holds "from above"; add "from the left"
    return ways[-1]
